import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"ColorGrid","description":"","frontmatter":{},"headers":[],"relativePath":"components/color-grid.md","filePath":"components/color-grid.md"}'),d={name:"components/color-grid.md"};function c(l,e,i,n,s,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="colorgrid" tabindex="-1">ColorGrid <a class="header-anchor" href="#colorgrid" aria-label="Permalink to &quot;ColorGrid&quot;">​</a></h1><p>ColorGrid is a grid of preset colors, of which one can be chosen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a small set of named colors, alone or at the top of a <a href="./color-picker">ColorPicker</a>. Each color needs a name, which is what a screen reader says; <code>label</code> names the group.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>colors</code></td><td>required</td><td><code>{ hex, name }[]</code></td></tr><tr><td><code>value</code></td><td></td><td>The chosen color, compared without regard to case</td></tr><tr><td><code>onselect</code></td><td>required</td><td>Called with the hex of the pressed color</td></tr><tr><td><code>label</code></td><td>required</td><td>The name of the group</td></tr><tr><td><code>columns</code></td><td><code>9</code></td><td>The number of columns</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The colors stand in columns gap-2xs apart and fill the width of the container; each cell is a square of the color itself, with a line inside, and nothing is placed in it. The chosen cell shows a ring inside, two lines of the focus color and one of the panel. The group is a <code>radiogroup</code> and each cell a <code>radio</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/color-grid/" title="ColorGrid" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/color-grid/" target="_blank" rel="noopener">ColorGrid</a></figcaption></figure>',10)])])}const u=o(d,[["render",c]]);export{m as __pageData,u as default};
